'use strict';
(() => {
  const $ = selector => document.querySelector(selector);
  const $$ = selector => [...document.querySelectorAll(selector)];
  const esc = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const normalise = value => String(value).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  const icon = name => `<svg aria-hidden="true"><use href="#${name}"/></svg>`;
  const amount = n => Number(n).toLocaleString('en-ZM',{maximumFractionDigits:2});
  const money = n => `<span class="money"><small>K</small>${amount(n)}</span>`;
  const plainMoney = n => `K${amount(n)}`;
  const meta = {
    food:[{id:'grill',name:'On the grill',icon:'flame'},{id:'platters',name:'Sharing platters',icon:'people',virtual:true},{id:'fried',name:'Fried selection',icon:'cutlery'},{id:'pot',name:'In the pot',icon:'pot'},{id:'sides',name:'Sides',icon:'cup'},{id:'extras',name:'Extras',icon:'plus'}],
    drinks:[{id:'spirits',name:'Spirits & liquor',icon:'bottle',note:'Choose your pour. Shot and bottle prices are shown separately.'},{id:'wines',name:'Wines',icon:'wine',note:'Wine prices are per bottle.'},{id:'sparkling',name:'Sparkling wines',icon:'wine',note:'Sparkling wine prices are per bottle.'},{id:'beers',name:'Beers, ciders & lagers',icon:'glass',note:'Bottle, can and dumpy prices are shown where available.'},{id:'mixers',name:'Mixers & cocktails',icon:'cup'},{id:'extras-drinks',name:'Shisha & extras',icon:'plus'}]
  };
  const photos = {'item-2':'assets/wings.webp','item-4':'assets/fish.webp','item-6':'assets/grill-platter.webp','item-7':'assets/grill-platter.webp','item-8':'assets/grill-platter.webp'};
  const photoDetails = {};
  const featureIds = ['item-2','item-6','item-4'];
  let items=[],mode='food',category='all',query='',favouritesOnly=false,guests=3,combo=[];
  let saved=new Set(),table=[],currentItem=null,chosenFormat=0,chosenQuantity=1;
  try{const stored=JSON.parse(localStorage.getItem('spillway-menu-saved-v1')||'[]');if(Array.isArray(stored))saved=new Set(stored.filter(id=>typeof id==='string'));}catch{}
  try{const stored=JSON.parse(localStorage.getItem('spillway-table-v1')||'[]');if(Array.isArray(stored))table=stored;}catch{}
  const findItem = id => items.find(i=>i.id===id);
  const findPrice = line => findItem(line.id)?.prices.find(p=>p.label===line.format);
  const keyFor = line => `${line.id}:${line.format}`;
  const getCategory = item => meta[item.group].find(c=>c.id===item.category);
  const matchesCategory = (item,id) => id==='all'||(id==='platters'?Boolean(item.tag):item.category===id);
  let toastTimer;
  function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2400);}
  function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{return false;}}
  function persistTable(){if(!persist('spillway-table-v1',table))toast('Your table is saved for this visit only.');}
  function renderCategories(){
    const food=items.filter(i=>i.group===mode);
    $('#category-nav').innerHTML=[{id:'all',name:mode==='food'?'All food':'All drinks'},...meta[mode]].map((c,index)=>`<button class="category-button ${!favouritesOnly&&category===c.id?'selected':''}" data-category="${c.id}" ${!favouritesOnly&&category===c.id?'aria-current="true"':''}><span class="category-number">${String(index).padStart(2,'0')}</span><span>${c.name}</span><span class="category-count">${food.filter(i=>matchesCategory(i,c.id)).length}</span></button>`).join('');
  }
  function saveButton(item,cls='save-button'){return `<button class="${cls} ${saved.has(item.id)?'is-saved':''}" data-save="${item.id}" aria-label="${saved.has(item.id)?'Unsave':'Save'} ${esc(item.name)}" aria-pressed="${saved.has(item.id)}">${icon('heart')}</button>`;}
  function featureCard(item){return `<article class="food-feature"><button class="feature-photo" data-detail="${item.id}" aria-label="View ${esc(item.name)} details"><img src="${photos[item.id]}" alt="Illustrative ${esc(item.name)} photograph" loading="lazy" width="480" height="360">${item.tag?`<span class="photo-label">${icon('people')}${esc(item.tag.toUpperCase())}</span>`:''}</button>${saveButton(item)}<div class="feature-info"><button class="item-name" data-detail="${item.id}">${esc(item.name)}</button><p class="feature-desc">${esc(item.description||'From our grill to your table.')}</p><div class="feature-bottom">${money(item.prices[0].amount)}<button class="add-circle" data-add="${item.id}" aria-label="Add ${esc(item.name)} to your table">${icon('plus')}</button></div></div></article>`;}
  function photoClass(item){return photoDetails[item.id]?.kind==='product'?'is-product':'is-food';}
  function rowPhoto(item){return `<button class="row-photo ${photoClass(item)}" data-detail="${item.id}" aria-label="View ${esc(item.name)} photo and details"><img src="${esc(photos[item.id])}" alt="${esc(photoDetails[item.id]?.alt||item.name)}" loading="lazy" decoding="async" width="90" height="90"></button>`;}
  function photoCredit(item){const data=photoDetails[item.id];if(!data?.source_url)return '';return `<p class="photo-credit">Photo: <a href="${esc(data.source_url)}" target="_blank" rel="noopener noreferrer">${esc(data.credit||'Image source')}</a>${data.license_url?` · <a href="${esc(data.license_url)}" target="_blank" rel="noopener noreferrer">${esc(data.license||'Licence')}</a>`:''}</p>`;}
  function rowPlaceholder(item){return `<button class="row-photo no-photo" data-detail="${item.id}" aria-label="View ${esc(item.name)} details">${icon(getCategory(item)?.icon||'glass')}</button>`;}
  function menuRow(item){return `<article class="menu-row">${photos[item.id]?rowPhoto(item):rowPlaceholder(item)}<button class="row-name" data-detail="${item.id}" aria-label="View ${esc(item.name)} details"><strong>${esc(item.name)}</strong>${item.tag?`<small class="row-tag">${esc(item.tag)}</small>`:''}${item.description?`<small>${esc(item.description)}</small>`:''}</button><div class="row-prices">${item.prices.map(p=>`<span class="row-price">${p.label?`<small>${esc(p.label)}</small>`:''}${money(p.amount)}</span>`).join('')}</div>${saveButton(item,'row-heart')}<button class="add-circle" data-add="${item.id}" aria-label="${item.prices.length>1?'Choose a serving of':'Add'} ${esc(item.name)}${item.prices.length>1?'':' to your table'}">${icon('plus')}</button></article>`;}
  function renderMenu(){
    renderCategories();$('#saved-count').textContent=saved.size;$('#favourites-toggle').setAttribute('aria-pressed',favouritesOnly);
    $$('[data-mode]').forEach(button=>{const active=button.dataset.mode===mode;button.classList.toggle('active',active);button.setAttribute('aria-selected',active);button.tabIndex=active?0:-1;});
    $('#menu-panel').setAttribute('aria-labelledby',favouritesOnly?'favourites-toggle':`${mode}-tab`);
    $('#clear-search').hidden=!query;
    $('#menu-search').placeholder=favouritesOnly?'Search your saved items…':mode==='food'?'What are you craving?':'Find your favourite drink…';
    const selected=items.filter(i=>(favouritesOnly?saved.has(i.id):i.group===mode&&matchesCategory(i,category))&&(!query||normalise([i.name,i.description,i.tag,getCategory(i)?.name].join(' ')).includes(normalise(query))));
    const suffix=favouritesOnly?(selected.length===1?'saved item':'saved items'):mode==='food'?(selected.length===1?'food item':'food items'):(selected.length===1?'drink or extra':'drinks & extras');
    $('#results-status').textContent=query?`${selected.length} ${selected.length===1?'match':'matches'} for “${query}”`:`${selected.length} ${suffix} · take your pick`;
    let html='';
    if(!selected.length){html=`<div class="empty-state">${icon(query?'search':'heart')}<h3>${query?'NO MATCHES THIS TIME.':'MAKE ROOM FOR FAVOURITES.'}</h3><p>${query?'Try another name or explore another menu.':'Tap a heart as you browse. Find your saved picks here.'}</p><button class="button blue" data-reset>${query?'Clear search':'Explore the menu'} ${icon('arrow')}</button></div>`;}
    else{
      if(mode==='drinks'&&!favouritesOnly&&!query&&category==='all')html+=`<div class="drinks-banner"><img src="assets/bar.webp" alt="Illustrative drinks from the bar" loading="lazy"><div><span class="eyebrow">THE SPILLWAY BAR</span><h3>POURED<br>YOUR WAY.</h3><p>Choose a favourite. Raise a glass.</p></div></div>`;
      for(const group of favouritesOnly?['food','drinks']:[mode]){
        const cats=meta[group].filter(c=>!c.virtual);
        for(const [index,c] of cats.entries()){
          const found=selected.filter(i=>i.category===c.id);if(!found.length)continue;
          const featured=c.id==='grill'?featureIds.map(id=>found.find(i=>i.id===id)).filter(Boolean):[];
          const rows=found.filter(i=>!featured.includes(i));
          const label=category==='platters'?'SHARING PLATTERS':c.name.toUpperCase();
          html+=`<section class="category-group"><div class="category-title"><span class="index">${String(index+1).padStart(2,'0')}</span><h3>${label}</h3></div>${c.note?`<p class="category-note">${c.note}</p>`:''}${featured.length?`<div class="feature-grid">${featured.map(featureCard).join('')}</div>`:''}${rows.length?`<div class="menu-rows ${rows.some(i=>i.prices.length>1)?'multi-price':''}">${rows.map(menuRow).join('')}</div>`:''}</section>`;
        }
      }
    }
    $('#menu-items').innerHTML=html;
  }
  function syncHash(){history.replaceState(null,'',favouritesOnly?'#saved':`#${mode}${category==='all'?'':'-'+category}`);}
  function clearQuery(){query='';$('#menu-search').value='';}
  function setMode(next,scroll=false){mode=next;category='all';favouritesOnly=false;clearQuery();renderMenu();syncHash();if(scroll)$('#menu').scrollIntoView({behavior:'smooth'});}
  function toggleSaved(id){if(!findItem(id))return;if(saved.has(id))saved.delete(id);else saved.add(id);persist('spillway-menu-saved-v1',[...saved]);renderMenu();if($('#item-dialog').open)updateDetailSave();toast(saved.has(id)?'Saved to your favourites.':'Removed from your favourites.');}
  function updateDetailSave(){if(!currentItem)return;const button=$('#item-dialog [data-save]');if(!button)return;button.classList.toggle('is-saved',saved.has(currentItem.id));button.setAttribute('aria-pressed',saved.has(currentItem.id));button.setAttribute('aria-label',`${saved.has(currentItem.id)?'Unsave':'Save'} ${currentItem.name}`);}
  function tableTotal(){return table.reduce((sum,line)=>sum+findPrice(line).amount*line.qty,0);}
  function tableCount(){return table.reduce((sum,line)=>sum+line.qty,0);}
  function updateTableCounts(){const count=tableCount();$$('.table-count').forEach(el=>el.textContent=count);$$('[data-open-table]').forEach(button=>button.setAttribute('aria-label',`View your table, ${count} ${count===1?'item':'items'}`));$('#floating-table').hidden=!count;$('#floating-count').textContent=`${count} ${count===1?'item':'items'}`;$('#floating-total').textContent=plainMoney(tableTotal());}
  function addToTable(item,priceIndex=0,qty=1,announce=true){const price=item.prices[priceIndex];const line=table.find(l=>l.id===item.id&&l.format===price.label);if(line)line.qty=Math.min(99,line.qty+qty);else table.push({id:item.id,format:price.label,qty:Math.min(99,qty)});persistTable();updateTableCounts();if($('#table-dialog').open)renderTable();if(announce)toast(`${qty} × ${item.name} added to your table.`);}
  function renderDetail(){
    const item=currentItem,cat=getCategory(item),photo=photos[item.id];
    $('#item-dialog-content').innerHTML=`<div class="dialog-photo ${photo?photoClass(item):'no-photo'}">${photo?`<img src="${photo}" alt="Illustrative ${esc(item.name)} photograph">`:icon(cat.icon)}<span>${item.group==='drinks'?'Good drinks.<br>Great times.':'Good food.<br>Good company.'}</span></div><div class="item-detail"><p class="eyebrow">${cat.name.toUpperCase()}</p><h2 id="item-dialog-title">${esc(item.name)}</h2>${item.tag?`<span class="detail-tag">${icon('people')}${esc(item.tag)}</span>`:''}${item.description?`<p class="detail-desc">${esc(item.description)}</p>`:''}<p class="format-label">${item.prices.length>1?'CHOOSE YOUR SERVING':'MENU PRICE'}</p><div class="format-options" role="group" aria-label="Serving format">${item.prices.map((p,index)=>`<button class="format-option ${chosenFormat===index?'selected':''}" data-format="${index}" aria-pressed="${chosenFormat===index}" aria-label="${esc(p.label||'Serving')}, ${plainMoney(p.amount)}"><span>${esc(p.label||'Serving')}</span>${money(p.amount)}</button>`).join('')}</div><div class="detail-quantity"><span>QUANTITY</span><div class="quantity-control"><button data-detail-qty="-1" aria-label="Decrease item quantity" ${chosenQuantity===1?'disabled':''}>${icon('minus')}</button><b id="detail-qty">${chosenQuantity}</b><button data-detail-qty="1" aria-label="Increase item quantity" ${chosenQuantity===99?'disabled':''}>${icon('plus')}</button></div></div><div class="detail-actions"><button class="button blue" id="detail-add">Add to table <span id="detail-add-price">${plainMoney(item.prices[chosenFormat].amount*chosenQuantity)}</span></button>${saveButton(item)}</div><p class="detail-note">Zambian kwacha (ZMW). Ask your server about availability and dietary needs.</p>${photoCredit(item)}</div>`;
  }
  function openDetail(id){const item=findItem(id);if(!item)return;currentItem=item;chosenFormat=0;chosenQuantity=1;renderDetail();$('#item-dialog').showModal();}
  function refreshDetailChoice(){const item=currentItem;$$('#item-dialog [data-format]').forEach(button=>{const active=Number(button.dataset.format)===chosenFormat;button.classList.toggle('selected',active);button.setAttribute('aria-pressed',active);});$('#detail-qty').textContent=chosenQuantity;$('#detail-add-price').textContent=plainMoney(item.prices[chosenFormat].amount*chosenQuantity);$('#item-dialog [data-detail-qty="-1"]').disabled=chosenQuantity===1;$('#item-dialog [data-detail-qty="1"]').disabled=chosenQuantity===99;}
  function renderTable(){
    if(!table.length){$('#table-items').innerHTML=`<div class="empty-state">${icon('bag')}<h3>GOOD TIMES<br>START HERE.</h3><p>Add food and drinks as you browse.<br>Your table will come together right here.</p><button class="button blue" id="table-browse">Explore the menu ${icon('arrow')}</button></div>`;$('#table-summary').innerHTML='';return;}
    $('#table-items').innerHTML=table.map(line=>{const item=findItem(line.id),price=findPrice(line),key=keyFor(line);return `<article class="table-line">${photos[item.id]?`<img class="table-line-img ${photoClass(item)}" src="${photos[item.id]}" alt="">`:`<span class="table-line-icon">${icon(getCategory(item).icon)}</span>`}<div class="table-line-body"><div class="table-line-head"><h3>${esc(item.name)}</h3>${money(price.amount*line.qty)}</div><p class="table-line-format">${esc(line.format||'Serving')} · ${plainMoney(price.amount)} each</p><div class="table-line-bottom"><div class="quantity-control"><button data-table-qty="-1" data-line="${esc(key)}" aria-label="Remove one ${esc(item.name)}${line.format?' '+esc(line.format):''}">${icon('minus')}</button><b>${line.qty}</b><button data-table-qty="1" data-line="${esc(key)}" aria-label="Add one ${esc(item.name)}${line.format?' '+esc(line.format):''}" ${line.qty===99?'disabled':''}>${icon('plus')}</button></div><button class="remove-line" data-remove="${esc(key)}" aria-label="Remove ${esc(item.name)}${line.format?' '+esc(line.format):''} from your table">Remove</button></div></div></article>`;}).join('');
    $('#table-summary').innerHTML=`<div class="table-total"><span>Estimated total</span>${money(tableTotal())}</div><button class="button blue table-copy" id="copy-table">Copy table list ${icon('copy')}</button><p class="table-summary-note">This is your table list. Show it to your server to order and confirm availability.</p><button class="clear-table" id="clear-table">Clear the table</button>`;
  }
  function openTable(){if($('#item-dialog').open)$('#item-dialog').close();renderTable();$('#table-dialog').showModal();}
  function changeTable(key,delta){const line=table.find(l=>keyFor(l)===key);if(!line)return;const item=findItem(line.id);line.qty=Math.max(0,Math.min(99,line.qty+delta));if(!line.qty)table=table.filter(l=>l!==line);persistTable();updateTableCounts();renderTable();if(table.length){const selector=delta>0?'[data-table-qty="1"]':'[data-table-qty="-1"]';$$(`#table-dialog ${selector}`).find(el=>el.dataset.line===key)?.focus({preventScroll:true});}else toast(`${item.name} removed. Your table is clear.`);}
  function bestPlatterCombination(n){const platters=items.filter(i=>i.tag).map(item=>({item,serves:Number(item.tag.match(/\d+/)[0]),price:item.prices[0].amount}));let best=null;const max=Math.ceil(n/3)+1;for(let a=0;a<=max;a++)for(let b=0;b<=max;b++)for(let c=0;c<=max;c++){const counts=[a,b,c],serves=counts.reduce((s,q,i)=>s+q*platters[i].serves,0);if(serves<n)continue;const total=counts.reduce((s,q,i)=>s+q*platters[i].price,0);if(!best||total<best.total||(total===best.total&&serves<best.serves))best={total,serves,entries:platters.map((p,i)=>({...p,qty:counts[i]})).filter(p=>p.qty)};}return best;}
  function renderPlatterFinder(){if(!items.length)return;const best=bestPlatterCombination(guests);combo=best.entries;$('#guest-count').textContent=guests;$('#guest-minus').disabled=guests===1;$('#guest-plus').disabled=guests===20;$('#platter-suggestion').innerHTML=`<p class="suggestion-names">${combo.map(p=>`${p.qty} × ${esc(p.item.name)}`).join('<br>')}</p><div class="suggestion-meta"><strong>${plainMoney(best.total)}</strong><span>${plainMoney(best.total/guests)} per person · serves ${best.serves}</span></div>`;}
  function renderPlatterLineup(){$('#platter-lineup').innerHTML=items.filter(i=>i.tag).sort((a,b)=>Number(a.tag.match(/\d+/)[0])-Number(b.tag.match(/\d+/)[0])).map(i=>`<button class="platter-tile" data-detail="${i.id}" aria-label="View ${esc(i.name)} details"><img class="platter-thumb" src="assets/grill-platter.webp" alt="" loading="lazy" width="100" height="100"><span><h3>${esc(i.name.toUpperCase())}</h3><p>${esc(i.tag)} ${money(i.prices[0].amount)}</p></span>${icon('arrow-up')}</button>`).join('');}
  function changeScene(scene){const bar=scene==='bar';const image=$('#hero-image');const next=bar?'assets/bar.webp':'assets/grill-platter.webp';image.classList.add('changing');const preload=new Image();preload.onload=()=>{image.src=next;image.alt=bar?'Illustrative drinks on the Spillway bar menu':'Illustrative grill sharing platter';image.classList.remove('changing');};preload.onerror=()=>image.classList.remove('changing');preload.src=next;$('#hero-title').innerHTML=bar?'SIP BACK.<br>SETTLE<br><span>RIGHT IN.</span>':'FIRE UP<br>YOUR<br><span>APPETITE.</span>';$('#hero-description').innerHTML=bar?'Your favourite pour. Something cold.<br>A little more time with your people.':'Flame-grilled favourites. Platters for your people.<br>Something cold on the side.';$('#hero-cta').dataset.explore=bar?'drinks':'food';$('#hero-cta').innerHTML=`${bar?'Explore the bar':'Explore the menu'} ${icon('arrow-up')}`;$('#hero-caption-label').textContent=bar?'A PROPER CHEERS':'THE MORE, THE MERRIER';$('#hero-caption-text').textContent=bar?'Good company deserves a good drink.':'Our platters bring the table together.';$$('[data-scene]').forEach(button=>{const active=button.dataset.scene===scene;button.classList.toggle('active',active);button.setAttribute('aria-pressed',active);});}
  $('#menu-items').addEventListener('click',event=>{const save=event.target.closest('[data-save]');if(save){const id=save.dataset.save;toggleSaved(id);$(`#menu-items [data-save="${id}"]`)?.focus({preventScroll:true});return;}const add=event.target.closest('[data-add]');if(add){const item=findItem(add.dataset.add);if(item.prices.length>1)openDetail(item.id);else addToTable(item);return;}const detail=event.target.closest('[data-detail]');if(detail){openDetail(detail.dataset.detail);return;}if(event.target.closest('[data-reset]')){if(query){clearQuery();renderMenu();$('#menu-search').focus();}else{favouritesOnly=false;renderMenu();syncHash();}}});
  $('#category-nav').addEventListener('click',event=>{const button=event.target.closest('[data-category]');if(!button)return;category=button.dataset.category;favouritesOnly=false;clearQuery();renderMenu();syncHash();const replacement=$(`[data-category="${category}"]`);replacement?.focus({preventScroll:true});replacement?.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'});});
  $$('[data-mode]').forEach(button=>{button.addEventListener('click',()=>setMode(button.dataset.mode));button.addEventListener('keydown',event=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const next=event.key==='Home'?'food':event.key==='End'?'drinks':mode==='food'?'drinks':'food';setMode(next);$(`#${next}-tab`).focus();}});});
  $$('[data-explore]').forEach(button=>button.addEventListener('click',()=>setMode(button.dataset.explore,true)));
  $$('[data-scene]').forEach(button=>button.addEventListener('click',()=>changeScene(button.dataset.scene)));
  $('#favourites-toggle').addEventListener('click',()=>{favouritesOnly=!favouritesOnly;clearQuery();renderMenu();syncHash();});
  $('#menu-search').addEventListener('input',event=>{query=event.target.value.trim();category='all';renderMenu();});$('#clear-search').addEventListener('click',()=>{clearQuery();renderMenu();$('#menu-search').focus();});
  $('#guest-minus').addEventListener('click',()=>{guests=Math.max(1,guests-1);renderPlatterFinder();});$('#guest-plus').addEventListener('click',()=>{guests=Math.min(20,guests+1);renderPlatterFinder();});
  $('#add-suggested').addEventListener('click',()=>{for(const p of combo)addToTable(p.item,0,p.qty,false);toast('Your platter combination is on the table.');});$('#platter-lineup').addEventListener('click',event=>{const button=event.target.closest('[data-detail]');if(button)openDetail(button.dataset.detail);});
  $$('[data-open-table]').forEach(button=>button.addEventListener('click',openTable));
  $$('[data-close]').forEach(button=>button.addEventListener('click',()=>$(`#${button.dataset.close}`).close()));
  $$('dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}));
  $('#item-dialog').addEventListener('click',event=>{const format=event.target.closest('[data-format]');if(format){chosenFormat=Number(format.dataset.format);refreshDetailChoice();return;}const quantity=event.target.closest('[data-detail-qty]');if(quantity){chosenQuantity=Math.max(1,Math.min(99,chosenQuantity+Number(quantity.dataset.detailQty)));refreshDetailChoice();return;}const save=event.target.closest('[data-save]');if(save){toggleSaved(save.dataset.save);return;}if(event.target.closest('#detail-add')){addToTable(currentItem,chosenFormat,chosenQuantity);$('#item-dialog').close();}});
  $('#table-dialog').addEventListener('click',async event=>{const quantity=event.target.closest('[data-table-qty]');if(quantity){changeTable(quantity.dataset.line,Number(quantity.dataset.tableQty));return;}const remove=event.target.closest('[data-remove]');if(remove){table=table.filter(line=>keyFor(line)!==remove.dataset.remove);persistTable();updateTableCounts();renderTable();return;}if(event.target.closest('#clear-table')){table=[];persistTable();updateTableCounts();renderTable();toast('A fresh start. Your table is clear.');return;}if(event.target.closest('#table-browse')){$('#table-dialog').close();$('#menu').scrollIntoView({behavior:'smooth'});return;}if(event.target.closest('#copy-table')){const text=['SPILLWAY CARWASH & GRILL','Your table list','',...table.map(line=>`${line.qty} × ${findItem(line.id).name}${line.format?' ('+line.format+')':''} — ${plainMoney(findPrice(line).amount*line.qty)}`),'',`Estimated total: ${plainMoney(tableTotal())}`,'Please confirm availability and order with your server.'].join('\n');try{await navigator.clipboard.writeText(text);const button=$('#copy-table');if(button){button.innerHTML='List copied '+icon('check');button.setAttribute('aria-live','polite');}toast('Table list copied. Show it to your server.');}catch{let field=$('#copy-fallback');if(!field){field=document.createElement('textarea');field.id='copy-fallback';field.className='copy-fallback';field.readOnly=true;field.setAttribute('aria-label','Table list to copy');$('#table-summary').append(field);}field.value=text;field.focus();field.select();toast('Your list is ready below. Select and copy it.');}}});
  function readHash(){const hash=location.hash.slice(1);if(hash==='saved'){favouritesOnly=true;return true;}const match=hash.match(/^(food|drinks)(?:-(.+))?$/);if(match){mode=match[1];category=meta[mode].some(c=>c.id===match[2])?match[2]:'all';favouritesOnly=false;return true;}return false;}
  window.addEventListener('hashchange',()=>{if(readHash()){clearQuery();renderMenu();$('#menu').scrollIntoView({behavior:'smooth'});}});
  document.addEventListener('keydown',event=>{if(event.key==='/'&&!$('dialog[open]')&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){event.preventDefault();$('#menu').scrollIntoView({behavior:'smooth'});$('#menu-search').focus({preventScroll:true});}});
  async function init(){try{const [response,imageResponse]=await Promise.all([fetch('menu.json'),fetch('menu-photos.json')]);if(!response.ok)throw new Error('Menu unavailable');items=await response.json();if(imageResponse.ok){const library=await imageResponse.json();for(const [id,data] of Object.entries(library)){if(findItem(id)&&typeof data.src==='string'&&data.src.startsWith('assets/')){photos[id]=data.src;photoDetails[id]=data;}}}saved=new Set([...saved].filter(id=>findItem(id)));table=table.filter(line=>line&&typeof line.id==='string'&&typeof line.format==='string'&&Number.isInteger(line.qty)&&line.qty>0&&line.qty<=99&&findPrice(line));const merged=new Map();for(const line of table){const key=keyFor(line);const previous=merged.get(key);if(previous)previous.qty=Math.min(99,previous.qty+line.qty);else merged.set(key,{id:line.id,format:line.format,qty:line.qty});}table=[...merged.values()];const linked=readHash();renderMenu();updateTableCounts();renderPlatterFinder();renderPlatterLineup();if(linked)requestAnimationFrame(()=>$('#menu').scrollIntoView());}catch(error){$('#results-status').textContent='The menu could not be loaded.';$('#menu-items').innerHTML='<div class="empty-state"><h3>LET’S TRY THAT AGAIN.</h3><p>Please reload the menu, or call +260 975 910 072.</p><button class="button blue" id="retry-menu">Reload menu</button></div>';$('#retry-menu').addEventListener('click',()=>location.reload());}}
  init();
})();
